#include <algorithm>
#include <array>
#include <fstream>
#include <string>
#include <vector>
int main() {
    std::ifstream in("notlast.in");
    std::ofstream out("notlast.out");
    const std::array<std::string, 7> names{"Bessie", "Elsie", "Daisy", "Gertie", "Annabelle", "Maggie", "Henrietta"};
    std::array<int, 7> totals{};
    int n;
    in >> n;
    for (int entry = 0; entry < n; ++entry) {
        std::string name;
        int milk;
        in >> name >> milk;
        for (int cow = 0; cow < 7; ++cow) if (names[cow] == name) totals[cow] += milk;
    }
    std::vector<int> levels(totals.begin(), totals.end());
    std::sort(levels.begin(), levels.end());
    levels.erase(std::unique(levels.begin(), levels.end()), levels.end());
    if (levels.size() < 2) {
        out << "Tie\n";
        return 0;
    }
    int selected = -1, matches = 0;
    for (int cow = 0; cow < 7; ++cow) {
        if (totals[cow] == levels[1]) {
            selected = cow;
            ++matches;
        }
    }
    out << (matches == 1 ? names[selected] : "Tie") << '\n';
}
