#include <fstream>
int main() {
    std::ifstream in("hps.in");
    std::ofstream out("hps.out");
    int n;
    in >> n;
    int a = 0, b = 0;
    for (int round = 0; round < n; ++round) {
        int first, second;
        in >> first >> second;
        const int direction = (second - first + 3) % 3;
        if (direction == 1) ++a;
        if (direction == 2) ++b;
    }
    out << std::max(a, b) << '\n';
}
