#include <fstream>
#include <string>
#include <vector>
int main() {
    std::ifstream in("cowtip.in");
    std::ofstream out("cowtip.out");
    int n;
    in >> n;
    std::vector<std::string> rows(n);
    for (std::string &row : rows) in >> row;
    const auto bit = [&](int r, int c) {
        return r < n && c < n ? rows[r][c] - '0' : 0;
    };
    int answer = 0;
    for (int r = 0; r < n; ++r)
        for (int c = 0; c < n; ++c)
            answer += bit(r, c) ^ bit(r + 1, c) ^ bit(r, c + 1) ^ bit(r + 1, c + 1);
    out << answer << '\n';
}
